from google.auth.transport.requests import Request
from google.oauth2.credentials import Credentials

def refresh_session(creds):
    if creds and creds.expired and creds.refresh_token:
        creds.refresh(Request())
        print('Session refreshed')
        return creds
    else:
        print('Error: Unable to refresh session')
        return None

from typing import Any, Dict

class UserInfo:
    def __init__(self, id: str, email: str, name: str):
        self.id = id
        self.email = email
        self.name = name

    @staticmethod
    def from_dict(data: Dict[str, Any]) -> 'UserInfo':
        return UserInfo(data.get('id'), data.get('email'), data.get('name'))

